#include <vector>
#include <stdexcept>
#include <algorithm>

void stencil(const std::vector<float>& x, std::vector<float>& y) {
    y.resize(x.size());
    for (std::size_t i = 0; i < x.size(); ++i) {
        float v = 2.0f * x[i];
        if (i > 0) v += x[i - 1];
        if (i + 1 < x.size()) v += x[i + 1];
        y[i] = v;
    }
}
```

